create extension if not exists pgcrypto;\ncreate table public.clients (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, name text not null, whatsapp text, address text, created_at timestamptz default now());\ncreate table public.quotes (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, client_id uuid references public.clients(id), service_type text not null, service text not null, status text default 'draft', total numeric(12,2) default 0, created_at timestamptz default now());\nalter table public.clients enable row level security; alter table public.quotes enable row level security;\ncreate policy own_clients on public.clients for all using(auth.uid()=user_id) with check(auth.uid()=user_id);\ncreate policy own_quotes on public.quotes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);